/* Vertiefung: eigenständige Lehrbeispiele für Datenbanken und Qualität. */
(function () {
  'use strict';
  function deepen(id, sections, question) {
    const lesson = COURSE.lessons.find(item => item.id === id);
    if (!lesson) throw new Error('Vertiefungslektion fehlt: ' + id);
    lesson.sections.push(...sections);
    lesson.questions.push(question);
  }
  deepen('er-modell', [
    S('Durchgearbeitet: Ausleihe als Beziehung mit eigenen Daten',
      `<p>Eine Bibliothek verwaltet Leser und Bücher. Ein Leser kann im Laufe der Zeit viele Bücher ausleihen; dasselbe Buch kann nacheinander von verschiedenen Lesern ausgeliehen werden. Ein Buch meint ein Exemplar mit eigener Nummer. Leser und Buch sind <b>Entitätstypen</b>; eine Ausleihe ist ein Vorgang. Der Rückgabetermin gehört weder dauerhaft zum Leser noch dauerhaft zum Buch, sondern zur jeweiligen Ausleihe.</p><ol><li>Identitäten festlegen: LeserNr und BuchNr sind unabhängig von veränderlichen Namen beziehungsweise Titeln.</li><li>Die zeitlich wiederholbare m:n-Beziehung durch Ausleihe auflösen.</li><li>Eine AusleiheNr als PK verwenden, weil derselbe Leser dasselbe Buch später erneut ausleihen darf.</li><li>LeserNr und BuchNr als FK in Ausleihe eintragen; jede Ausleihe verweist auf genau einen Leser und genau ein Buch.</li></ol>` + C('Leser(LeserNr PK, Name)\nBuch(BuchNr PK, Titel)\nAusleihe(AusleiheNr PK, LeserNr FK, BuchNr FK, Beginn, FaelligAm)') + `<p><b>Auf Leser- und Buchseite</b> sind jeweils 0..n Ausleihen möglich. Die Regel „höchstens eine aktuell offene Ausleihe pro Exemplar“ ist zusätzlich zu modellieren beziehungsweise technisch abzusichern. Die historische Gesamtzahl der Ausleihen verrät nicht, wie viele gleichzeitig erlaubt sind.</p>`,
      `<p><b>ابدأ بتحديد الشيء الذي نتتبعه:</b> المقصود بـBuch هنا نسخة مادية محددة، لا عنوان الكتاب الذي قد تتوفر منه نسخ عديدة. بعد ذلك اسأل أين تنتمي المعلومة. تاريخ الاستحقاق FaelligAm يخص عملية استعارة معينة؛ وضعه داخل Leser سيمنع تسجيل مواعيد مختلفة لكتب العميل، ووضعه داخل Buch سيمحو التاريخ عند الاستعارة التالية.</p><p><b>تحويل m:</b>n إلى <b>جدول وسيط</b> ليس مجرد رسم صندوق إضافي. جدول Ausleihe يحفظ العلاقة وسماتها، وكل صف فيه عملية مستقلة. لا تجعل زوج LeserNr وBuchNr مفتاحًا وحيدًا دون فحص قاعدة العمل، لأن الشخص يمكن أن يستعير النسخة نفسها مرة أخرى. اخترنا AusleiheNr حتى نستوعب التكرار عبر الزمن. اقرأ الكاردينالية في الاتجاهين: القارئ قد يملك عدة عمليات، لكن العملية الواحدة لها قارئ واحد فقط. شرط منع استعارتين مفتوحتين للنسخة نفسها يحتاج قاعدة إضافية؛ المفاتيح الأجنبية وحدها لا تمنعه.</p>`),
    S('Fehler verstehen und prüfungsfähig begründen',
      `<p><b>Typischer Fehler:</b> Name als <b>Primärschlüssel</b>. Namen können doppelt auftreten und sich ändern; ein stabiler Schlüssel trennt Identität von Beschreibung. Ein weiterer Fehler ist eine Fremdschlüsselliste wie „3,8,12“ in einem Feld: einzelne Beziehungen lassen sich dann kaum mit <b>referenzieller Integrität</b> sichern. Schreibe stattdessen je Beziehung einen Datensatz. Prüfe auch Optionalität: „kann ausleihen“ bedeutet nicht „muss bereits ausgeliehen haben“.</p><p><b>Kurze Prüfungsantwort:</b> „Die <b>m:n-Beziehung</b> wird durch Ausleihe mit zwei Fremdschlüsseln aufgelöst. Beginn und Fälligkeit sind <b>Beziehungsattribute</b>. Eine eigene AusleiheNr erlaubt wiederholte Ausleihen derselben Kombination.“ Zeichne anschließend die Schlüssel und die <b>Kardinalitäten</b>; ein fachlich richtiger Text ersetzt eine ausdrücklich verlangte Zeichnung nicht.</p>`,
      `<p>الخطأ الشائع هو الانطلاق من أسماء أعمدة موجودة بدل قواعد العمل. لا تختَر الاسم الشخصي مفتاحًا لأنه يبدو سهل القراءة، ولا تضع قائمة أرقام في خانة واحدة لتجنب <b>جدول العلاقة</b>. راجع أيضًا معنى «يمكن»: غياب استعارات لقارئ جديد حالة صحيحة، لذلك تكون البداية صفرًا. في جواب الامتحان اكتب السبب المرتبط بالمثال، مثل أن تاريخ الاستحقاق يختلف من استعارة لأخرى، ثم مثّل PK وFK والأعداد المطلوبة. العبارة «نضيف جدولًا لتحسين قاعدة البيانات» عامة ولا توضّح المشكلة التي حللتها.</p>`)
  ], Q('Ein Sportverein verwaltet Person(PersonNr,Name), Kurs(KursNr,Titel). Eine Person kann denselben Kurs in mehreren Semestern belegen. Modelliere die Teilnahme mit Note und erkläre einen passenden Schlüssel.',
    'Teilnahme(PersonNr PK/FK, KursNr PK/FK, Semester PK, Note) ist unter der Annahme höchstens einer Teilnahme pro Person/Kurs/Semester geeignet. Alternativ TeilnahmeNr als PK und UNIQUE(PersonNr,KursNr,Semester). Person und Kurs haben jeweils 0..n Teilnahmen; jede Teilnahme gehört genau einer Person und einem Kurs. Die Note gehört zur Teilnahme.',
    'الفصل الدراسي جزء من هوية المشاركة إذا كان تكرار الدورة مسموحًا. اذكر افتراض عدم تكرارها داخل الفصل نفسه؛ وإلا تحتاج معرفًا أو تمييزًا إضافيًا.', 8));

  deepen('normalisierung', [
    S('Durchgearbeitet: Abhängigkeiten zuerst, Tabellen danach',
      `<p><b>Gegeben ist eine Tabelle mit atomaren Werten:</b> BestellNr, ArtikelNr, KundeNr, Kundenname, Artikelname, Menge. Der Schlüssel ist (BestellNr, ArtikelNr). Annahmen: Jede Bestellung gehört genau einem Kunden; jede Artikelnummer bestimmt einen Artikelnamen; jede Kundennummer bestimmt einen Kundennamen. Menge beschreibt dagegen den Artikel innerhalb einer bestimmten Bestellung.</p><ol><li><b>1NF:</b> Keine Listen oder wiederholenden Spaltengruppen; ein Wert je Feld. Dies ist bereits erfüllt.</li><li><b>2NF:</b> Alle Nichtschlüsselattribute müssen vom gesamten Kandidatenschlüssel abhängen. Artikelname hängt nur von ArtikelNr ab; KundeNr und Kundenname bereits von BestellNr. Trenne Artikel und Bestellung ab.</li><li><b>3NF:</b> In Bestellung hängt Kundenname über KundeNr transitiv von BestellNr ab. Trenne Kunde ab; Bestellung behält KundeNr als FK.</li></ol>` + C('Kunde(KundeNr PK, Kundenname)\nBestellung(BestellNr PK, KundeNr FK)\nArtikel(ArtikelNr PK, Artikelname)\nPosition(BestellNr PK/FK, ArtikelNr PK/FK, Menge)') + `<p>Zur Kontrolle lässt sich die Ursprungssicht durch <b>JOIN</b> rekonstruieren. Eine Namensänderung betrifft nun genau den zuständigen Stammdatensatz. Menge bleibt in Position, weil sie weder vom Artikel allein noch von der Bestellung allein bestimmt wird.</p>`,
      `<p><b>التطبيع</b> ليس قاعدة «كل اسم في جدول منفصل». الأداة الأساسية هي <b>الاعتماد الوظيفي</b>: إذا عرفنا BestellNr نعرف العميل، وإذا عرفنا ArtikelNr نعرف اسم المنتج، لكن لا نعرف الكمية إلا بعد معرفة الطلب والمنتج معًا. لهذا تبقى Menge داخل Position.</p><p>في الخطوة الثانية ننقل الأعمدة التي تعتمد على جزء من <b>المفتاح المركب</b>. بعدها نفحص الجدول الجديد Bestellung: اسم العميل ما زال يعتمد على KundeNr، وهذا اعتماد انتقالي يجب فصله في <b>3NF</b>. لا تقفز مباشرة إلى الشكل النهائي دون فهم المرحلتين، لأن السؤال قد يطلب تحديد مخالفة محددة. بعد التقسيم تحقق أن الروابط تسمح بإعادة المعلومات الأصلية دون فقد أو صفوف وهمية. النتيجة المفيدة أن تغيير اسم العميل يتم مرة واحدة، وأننا نستطيع إنشاء منتج جديد دون اختراع طلب له، وحذف آخر طلب لا يحذف بيانات المنتج الأساسية.</p>`),
    S('Anomalien gezielt erkennen',
      `<p><b>Änderungsanomalie:</b> Derselbe Kundenname steht in vielen Positionen; nur einige werden korrigiert. <b>Einfügeanomalie:</b> Ein neuer Artikel kann ohne Bestellung nicht sinnvoll erfasst werden. <b>Löschanomalie:</b> Beim Entfernen der letzten Position verschwinden möglicherweise die einzigen Stammdaten des Artikels. Nenne jeweils die konkrete verlorene oder widersprüchliche Information.</p><p>Ein künstlicher ID-Schlüssel allein behebt keine Normalisierungsprobleme: dieselben fachlichen Abhängigkeiten bleiben bestehen. Prüfe <b>Kandidatenschlüssel</b> und Regeln, nicht nur die ausgewählte PK-Spalte. <b>Prüfungsantwort:</b> „Artikelname hängt nur von ArtikelNr ab, also von einem Teil des <b>zusammengesetzten Schlüssels</b>. Ein eigener Artikel-Datensatz beseitigt diese <b>partielle Abhängigkeit</b>.“</p>`,
      `<p>ميّز اسم المشكلة عن المثال الذي يثبتها. عند <b>Änderungsanomalie</b> اشرح أن تحديث بعض التكرارات فقط يولّد أسماء متعارضة. عند <b>Löschanomalie</b> حدّد أي معرفة ستضيع مع آخر صف. إضافة عمود ID لا تعالج هذه التكرارات؛ هي تغيّر وسيلة تعريف الصف فقط. في جواب الامتحان اذكر الاعتماد والمرحلة المخالفة والتقسيم المقترح، بدل عبارة «هناك بيانات مكررة» وحدها. التكرار أحيانًا مقصود لأسباب تشغيلية، لكن أي <b>Denormalisierung</b> يحتاج قرارًا واعيًا وضمانات اتساق بعد تصميم منطقي سليم.</p>`)
  ], Q('Tabelle Kursbelegung(PersonNr,KursNr,PersonName,KursTitel,RaumNr,RaumName,Note), PK=(PersonNr,KursNr). KursNr bestimmt KursTitel und RaumNr; RaumNr bestimmt RaumName. Zerlege bis 3NF.',
    'Person(PersonNr PK,PersonName); Raum(RaumNr PK,RaumName); Kurs(KursNr PK,KursTitel,RaumNr FK); Belegung(PersonNr PK/FK,KursNr PK/FK,Note). PersonName und Kursdaten sind partiell abhängig; RaumName ist über RaumNr transitiv von KursNr abhängig. Annahme: Jeder Kurs hat genau einen Raum und jede Person je Kurs höchstens eine Belegung.',
    'ابدأ بالاعتماد على PersonNr أو KursNr منفردًا، ثم افصل اسم الغرفة لأنه يتحدد عبر RaumNr. تبقى الدرجة في العلاقة لأنها تخص الطالب والدورة معًا.', 10));

  deepen('sql-select', [
    S('Durchgearbeitet: SQL als schrittweise Mengenwahl',
      `<p>Beispieldaten Artikel(id,name,preis,kategorie): (1,Heft,3.50,Buero), (2,Stift,1.80,Buero), (3,Mappe,7.00,Buero), (4,Spiel,12.00,Freizeit), (5,Tasche,NULL,Freizeit). Gesucht sind Büroartikel mit Preis von mindestens 3 €, teuerste zuerst. <b>WHERE</b> wählt passende Zeilen; <b>SELECT</b> bestimmt anschließend die ausgegebenen Spalten.</p>` + C("SELECT id, name, preis\nFROM Artikel\nWHERE kategorie = 'Buero' AND preis >= 3.00\nORDER BY preis DESC, id ASC;") + `<table><thead><tr><th>id</th><th>name</th><th>preis</th></tr></thead><tbody><tr><td>3</td><td>Mappe</td><td>7.00</td></tr><tr><td>1</td><td>Heft</td><td>3.50</td></tr></tbody></table><p><b>Prüfe die Bedingungen getrennt:</b> Stift erfüllt die Kategorie, aber nicht den Mindestpreis. Spiel erfüllt den Preis, aber nicht die Kategorie. Tasche hat einen unbekannten Preis; ein Preisvergleich wird nicht TRUE. Der zweite Sortierschlüssel macht die Reihenfolge bei gleichem Preis eindeutig. „Alle Artikel ohne bekannten Preis“ lautet <code>WHERE preis IS NULL</code>; <code>= NULL</code> liefert dafür keinen passenden Wahrheitswert. <b>BETWEEN</b> 3 AND 7 schließt beide Grenzen ein. Für einen Zeitraum mit Uhrzeiten ist eine untere inklusive und obere exklusive Grenze oft sicherer als eine erfundene Tagesendzeit.</p>`,
      `<p><b>نفّذ الاستعلام ذهنيًا بترتيب واضح:</b> انطلق من الجدول، افحص الشرط لكل صف، اختر الأعمدة، ثم رتّب. وجود AND يعني أن المنتج يجب أن يحقق الشرطين؛ لا يكفي سعر مناسب مع فئة مختلفة. النتيجة تحتوي Mappe ثم Heft، لأن DESC يجعل السعر الأعلى أولًا.</p><p>القيمة NULL ليست صفرًا ولا نصًا فارغًا. معناها هنا أن السعر غير معروف، لذلك لا نعرف إن كان أكبر من ثلاثة. لا تستخدم preis = NULL للبحث عنها؛ استخدم <b>IS NULL</b>. وإذا طُلب شمول السعر المجهول مع الأسعار العالية، عبّر عن ذلك صراحة بشرط OR. عند إدخال OR إلى شرط مركّب استخدم الأقواس لتوضيح المجموعة المقصودة. انتبه أيضًا إلى أن تحديد أعمدة <b>SELECT</b> لا يغيّر أي بيانات مخزّنة، وأن <b>ORDER BY</b> يؤثر على عرض النتيجة لا على ترتيب دائم للجدول.</p>`),
    S('Drei Fehler, die richtige Daten aus der Ausgabe entfernen',
      `<p><b>Erstens:</b> AND durch OR ersetzen erweitert die Ergebnismenge ungewollt. Zweitens: <code>preis &lt;&gt; 0</code> umfasst NULL nicht; UNKNOWN wird in <b>WHERE</b> ausgeschlossen. Drittens: Ohne <b>ORDER BY</b> ist keine fachlich garantierte Reihenfolge gegeben, auch wenn eine Datenbank zufällig nach ID liefert. Für Texte beachten: <code>LIKE 'A%'</code> findet einen Anfang A; <code>_</code> steht für ein Zeichen. Groß-/Kleinschreibung hängt von DBMS und Kollation ab.</p><p><b>Prüfungsantwort:</b> „<b>WHERE</b> filtert Zeilen anhand einer Bedingung. <b>IS NULL</b> prüft auf fehlende Werte; <b>ORDER BY</b> legt die geforderte Sortierung fest.“ Liefere bei einer SQL-Aufgabe den vollständigen Befehl, nicht nur diese Erklärung.</p>`,
      `<p>لا تستنتج ترتيبًا مضمونًا لأن البيانات ظهرت مرتبة مرة واحدة. إذا طلب السؤال ترتيبًا فاكتبه. كذلك لا تتوقع أن «ليس صفرًا» تشمل القيمة غير المعروفة؛ المقارنة مع NULL لا تكون صحيحة. في <b>LIKE</b> يختلف الرمز % عن _: الأول يسمح بعدد متغير من المحارف، والثاني بمحرف واحد. إن كان السؤال يحدد صيغة أو دالة في Belegsatz فاتبعها بدل خلط لهجات مختلفة. اكتب الشرط كاملًا مع الأقواس عند الحاجة، لأن فكرة صحيحة بصياغة شرط خاطئة تعطي صفوفًا مختلفة.</p>`)
  ], Q('Artikel(id,name,preis) enthält (1,A,10),(2,B,NULL),(3,C,0),(4,D,15). Schreibe SQL für bekannte Preise größer 0, absteigend, und nenne Ergebnis-IDs.',
    'SELECT id,name,preis FROM Artikel WHERE preis > 0 ORDER BY preis DESC,id ASC; Ergebnis: 4,1. IS NOT NULL wäre hier redundant, aber zulässig: preis>0 wird für NULL nicht TRUE. preis>=0 würde Artikel3 zusätzlich einschließen.',
    'B مستبعد لأن السعر مجهول، وC مستبعد لأنه يساوي الصفر. ليس مطلوبًا كتابة IS NOT NULL إذا كانت المقارنة نفسها تستبعد NULL، لكن افهم لماذا.', 6));
  deepen('sql-joins', [
    S('Durchgearbeitet: Warum aus zwei Kunden drei Zeilen werden',
      `<p><b>Tabellen:</b> Kunde(id,name) enthält (1,Ada), (2,Bilal), (3,Clara). Bestellung(id,kunde_id,status) enthält (10,1,bezahlt), (11,1,offen), (12,2,offen). Wir möchten alle Kunden und ihre bezahlten Bestellungen anzeigen, auch wenn keine solche Bestellung existiert. Starte deshalb links bei Kunde und beschränke passende rechte Zeilen bereits in ON.</p>` + C("SELECT k.id, k.name, b.id AS bestellung\nFROM Kunde k\nLEFT JOIN Bestellung b\n  ON b.kunde_id = k.id AND b.status = 'bezahlt'\nORDER BY k.id, b.id;") + `<table><thead><tr><th>id</th><th>name</th><th>bestellung</th></tr></thead><tbody><tr><td>1</td><td>Ada</td><td>10</td></tr><tr><td>2</td><td>Bilal</td><td>NULL</td></tr><tr><td>3</td><td>Clara</td><td>NULL</td></tr></tbody></table><p>Ada hat einen passenden Treffer. Bilals offene Bestellung erfüllt ON nicht; seine linke Zeile bleibt trotzdem erhalten. Clara hat gar keine Bestellung und erhält ebenfalls NULL für rechte Spalten. Ohne Statusbedingung wären es vier Zeilen, weil Ada zwei Bestellungen hat. Ein <b>JOIN</b> liefert Kombinationen passender Zeilen, nicht automatisch eine Zeile pro Kunde. Benötigst du genau Kunden ohne bezahlte Bestellung, ergänzt du <code>WHERE b.id IS NULL</code>. Wähle dafür eine rechte Spalte, die bei einem echten Treffer garantiert nicht NULL ist.</p>`,
      `<p><b>ابدأ بالسؤال:</b> من يجب ألا يختفي؟ المطلوب جميع العملاء، لذلك Kunde على يسار <b>LEFT JOIN</b>. الشرط في ON لا يحذف العميل الذي لا يملك طلبًا مدفوعًا؛ يحدّد فقط أي طلب يجوز ربطه به. لهذا يحصل Bilal على NULL رغم امتلاكه طلبًا مفتوحًا: ليس هناك طلب مطابق للشروط.</p><p>لا تتعامل مع <b>JOIN</b> كأنه يضيف عمودًا واحدًا إلى كل صف. إذا وجد عميلان مع ثلاثة طلبات، فالنتيجة تعتمد عدد التطابقات، لا عدد العملاء وحده. عند حذف شرط الحالة يظهر Ada مرتين، صف لكل طلب. وإذا أردت تجميعًا على مستوى العميل فلا تحاول إصلاح ذلك عشوائيًا بـDISTINCT؛ حدّد أولًا ما تريد حسابه ثم استخدم <b>GROUP BY</b> أو <b>EXISTS</b> المناسبين. لاكتشاف العملاء بلا طلب مدفوع افحص b.id <b>IS NULL</b> بعد الربط، لأن هذا العمود لا يكون فارغًا في الطلب الحقيقي.</p>`),
    S('ON und WHERE erfüllen unterschiedliche Aufgaben',
      `<p>Verschiebst du <code>b.status = 'bezahlt'</code> nach <b>WHERE</b>, werden Bilal und Clara entfernt: Der Vergleich mit den erzeugten NULL-Werten ist nicht TRUE. Selbst <code>OR b.id IS NULL</code> rettet Bilal nicht zuverlässig, wenn zunächst seine offene Bestellung verknüpft wurde. Formuliere die gewünschte Menge zuerst in Worten.</p><p><b>Prüfungsantwort:</b> „<b>LEFT JOIN</b> erhält jede linke Zeile. Der Filter in ON begrenzt rechte Treffer; ein Filter auf rechte Spalten in <b>WHERE</b> kann die erzeugten NULL-Zeilen anschließend ausschließen.“ Bei drei Tabellen prüfe jeden Beziehungspfad und jede Schlüsselverbindung, damit fehlende ON-Bedingungen kein <b>kartesisches Produkt</b> erzeugen.</p>`,
      `<p>الفرق هنا منطقي وليس مسألة سرعة فقط. <b>WHERE</b> يأتي بعد تكوين الصفوف، لذلك يمكنه إزالة ما حافظ عليه <b>LEFT JOIN</b>. الحل ليس إضافة OR NULL تلقائيًا؛ قد توجد للعميل طلبات غير مطابقة فتمنع أصلًا إنشاء الصف الفارغ الذي تتوقعه. اكتب شرط مطابقة الطلبات داخل ON عندما يجب حفظ جميع العملاء. في الامتحان ارسم صفين صغيرين لتبرهن الفكرة ثم قدّم الاستعلام كاملًا. تحقق أن كل ربط يستخدم مفاتيح صحيحة، لا أسماء قد تتكرر فتضاعف النتيجة دون قصد.</p>`)
  ], Q('Kunde enthält IDs1,2. Bestellung enthält (10,1,offen),(11,1,offen). Welche Zeilen liefert LEFT JOIN mit b.status=bezahlt in ON, und welche mit demselben Filter in WHERE?',
    'Filter in ON: Kunde1/NULL und Kunde2/NULL. Filter nur in WHERE: keine Zeilen; Kunde1 hat nur offene Treffer, Kunde2 einen NULL-Platzhalter, beide erfüllen den Statusvergleich nicht. SELECT k.id,b.id FROM Kunde k LEFT JOIN Bestellung b ON b.kunde_id=k.id AND b.status=\'bezahlt\'; erhält beide.',
    'وجود طلب غير مدفوع لا يعني وجود تطابق. شرط ON يختار الطلبات المدفوعة قبل قرار الإبقاء على العميل؛ WHERE يحذف الصفوف الناتجة بعد ذلك.', 7));

  deepen('sql-gruppen', [
    S('Durchgearbeitet: Erst filtern, dann gruppieren, dann Gruppen auswählen',
      `<p><b>Bestellung(id</b>,kunde_id,betrag,status) enthält (1,7,100,bezahlt), (2,7,200,bezahlt), (3,7,900,offen), (4,8,80,bezahlt), (5,8,NULL,bezahlt). Gesucht: je Kunde Anzahl bezahlter Bestellungen und deren Gesamtbetrag, aber nur Gruppen mit mindestens 250 € Gesamtbetrag. Der offene Auftrag darf keinen Betrag beitragen.</p>` + C("SELECT kunde_id, COUNT(*) AS anzahl, SUM(betrag) AS gesamt\nFROM Bestellung\nWHERE status = 'bezahlt'\nGROUP BY kunde_id\nHAVING SUM(betrag) >= 250\nORDER BY gesamt DESC, kunde_id;") + `<table><thead><tr><th>kunde_id</th><th>anzahl</th><th>gesamt</th></tr></thead><tbody><tr><td>7</td><td>2</td><td>300</td></tr></tbody></table><p><b>WHERE</b> entfernt zuerst Auftrag3. Kunde7 besitzt danach zwei Zeilen mit Summe300. Kunde8 besitzt ebenfalls zwei Zeilen, aber SUM ignoriert den unbekannten Betrag und ergibt80. Diese Gruppe scheitert an <b>HAVING</b>. <b>COUNT(*)</b> für Kunde8 wäre2, COUNT(betrag) dagegen1. Ein unbekannter Betrag ist fachlich nicht zwingend null Euro; <b>COALESCE</b> kann eine Darstellungsentscheidung sein, darf aber ungeklärte Geschäftsdaten nicht verschleiern. Möchtest du Kunden ohne Bestellungen einschließen, brauchst du zusätzlich die Kundentabelle und <b>LEFT JOIN</b>; die alleinige Bestellungstabelle kann nicht vorhandene Kunden nicht erzeugen.</p>`,
      `<p><b>افصل المستويات الثلاثة:</b> <b>WHERE</b> يختار الطلبات المدفوعة، <b>GROUP BY</b> يجمعها حسب العميل، وHAVING يقرر أي مجموعة تبقى بعد حساب المجموع. إدخال مبلغ الطلب المفتوح سيجعل النتيجة خاطئة حتى لو كانت صيغة <b>SUM</b> سليمة.</p><p>لدى Kunde8 طلبان مدفوعان، لكن مبلغ أحدهما مجهول. <b>COUNT(*)</b> يحسب الصفين، وCOUNT(betrag) يحسب مبلغًا واحدًا معروفًا، وSUM يجمع الثمانين المعروفة فقط. لهذا لا تشرح NULL بأنها «صفر»؛ تجاهل القيمة في الحساب ليس إثباتًا أن مبلغها يساوي صفرًا. إذا كنت تعدّ الطلبات بعد ربطها بجدول Position، فقد يظهر الطلب عدة مرات ويحتاج العدّ <b>COUNT</b>(<b>DISTINCT</b> id) حسب المطلوب. فكّر في مستوى الصف: هل يمثل طلبًا، أم سطر طلب، أم عميلًا؟ هذه الخطوة تمنع معظم أخطاء التقارير، وهي أهم من حفظ ترتيب الكلمات وحده.</p>`),
    S('Doppelzählung und Durchschnitt richtig begründen',
      `<p>Eine Bestellung mit drei Positionen erscheint nach dem <b>JOIN</b> dreimal. <b>SUM</b> des bereits gespeicherten Bestellgesamtbetrags würde ihn verdreifachen; <b>SUM</b> der drei Positionsbeträge kann dagegen richtig sein. Die geeignete <b>Aggregation</b> hängt von der Zeilenbedeutung ab. <b>DISTINCT</b> auf einem Geldbetrag ist keine allgemeine Reparatur: Zwei verschiedene Bestellungen können zufällig denselben Betrag haben.</p><p>Auch „Durchschnitt aller Einzelpreise“ und „Umsatz je verkauftem Stück“ sind verschieden. Letzterer ist <code>SUM(menge*preis)/SUM(menge)</code>. <b>Prüfungsantwort:</b> „<b>WHERE</b> filtert einzelne Zeilen, <b>HAVING</b> berechnete Gruppen. Nichtaggregierte Ausgabespalten werden für portables SQL passend gruppiert.“</p>`,
      `<p>إذا أصبح كل طلب ثلاثة صفوف بسبب ربط تفاصيله، فلا تجمع قيمة الطلب الكلية ثلاث مرات. اختر مستوى الحساب الصحيح أو اجمع التفاصيل أولًا. كذلك <b>SUM</b>(<b>DISTINCT</b> betrag) قد يحذف مبلغين متساويين يعودان لطلبين مختلفين، فلا يصلح كعلاج عام للتكرار. المتوسط الموزون يحتاج الكميات؛ منتج بيع منه مئة قطعة لا يملك وزن منتج بيع منه قطعة واحدة. اشرح في جوابك ما الذي يمثله كل صف وما وحدة الناتج، ثم اختر <b>COUNT</b> أو <b>SUM</b> أو <b>AVG</b> المناسبة.</p>`)
  ], Q('Position(bestellung_id,menge,preis) enthält (1,2,10),(1,1,20),(2,3,5). Berechne je Bestellung Umsatz und Stückzahl in SQL und nenne die Ergebnisse.',
    'SELECT bestellung_id,SUM(menge*preis) AS umsatz,SUM(menge) AS stueck FROM Position GROUP BY bestellung_id ORDER BY bestellung_id; Ergebnis Bestellung1: Umsatz40, Stück3; Bestellung2: Umsatz15, Stück3. AVG(preis) oder SUM(preis) ersetzen keine Umsatzrechnung.',
    'سعر السطر ليس ثمن القطعة وحده؛ نضرب بالكمية. استخدم SUM(menge) لعدد القطع، لا COUNT(*) الذي يحسب أسطر التفاصيل.', 7));

  deepen('sql-subqueries', [
    S('Durchgearbeitet: Ein Bericht mit zwei Aggregationsebenen',
      `<p>Bestellung(id,kunde_id) enthält (1,10), (2,10), (3,20), (4,20), (5,20), (6,30). Frage: Wie viele Bestellungen haben bestellende Kunden durchschnittlich? Zuerst brauchst du eine Zahl je Kunde; erst danach darfst du den Durchschnitt dieser Zahlen bilden. Das innere <b>SELECT</b> ist hier eine abgeleitete Tabelle mit dem Namen x.</p>` + C('SELECT AVG(1.0 * x.anzahl) AS durchschnitt\nFROM (\n  SELECT kunde_id, COUNT(*) AS anzahl\n  FROM Bestellung\n  GROUP BY kunde_id\n) AS x;') + `<table><thead><tr><th>Zwischenergebnis: kunde_id</th><th>anzahl</th></tr></thead><tbody><tr><td>10</td><td>2</td></tr><tr><td>20</td><td>3</td></tr><tr><td>30</td><td>1</td></tr></tbody></table><p>Der äußere Durchschnitt beträgt (2+3+1)/3 =2. Die Multiplikation mit1.0 verlangt eine nicht ganzzahlige Rechnung; Details des Rückgabetyps hängen vom DBMS ab. Ein Kunde40 ohne Bestellung fehlt im inneren Ergebnis. Soll er mit0 zählen, muss die innere Abfrage bei Kunde beginnen und mit <b>LEFT JOIN</b> sowie <b>COUNT</b>(b.id) arbeiten. „Durchschnitt pro Kunde“ benötigt also eine genaue <b>Grundgesamtheit</b>. Eine reine <b>AVG</b>-Abfrage auf einzelnen Bestellzeilen kann die benötigten Kundenzahlen nicht ersetzen; du würdest auf der falschen Ebene rechnen.</p>`,
      `<p>المطلوب متوسط عدد الطلبات، وليس متوسط رقم الطلب أو متوسط مبالغه. لهذا نعمل على مرحلتين: <b>الاستعلام الداخلي</b> ينتج صفًا واحدًا لكل عميل، ثم الخارجي يحسب المتوسط لهذه الصفوف. الأعداد هي اثنان وثلاثة وواحد، فالمتوسط اثنان.</p><p><b>اسأل دائمًا من يدخل المقام:</b> «العملاء الذين طلبوا» يختلف عن «جميع العملاء». إذا كان هناك عميل رابع بلا طلب، يصبح المتوسط بين الجميع ستة على أربعة، أي 1.5. لإدخاله نبدأ من Kunde ونربط الطلبات اختياريًا ونعد b.id، لا <b>COUNT(*)</b> الذي قد يعدّ الصف الفارغ كطلب. الاسم x ليس جدولًا دائمًا جديدًا؛ هو تسمية لنتيجة مؤقتة داخل هذا الاستعلام. القاعدة المفيدة أن كل مستوى تجميع يجيب سؤالًا واحدًا واضحًا، ثم تستخدم نتيجته لحساب المستوى التالي.</p>`),
    S('EXISTS und NULL: Auf die Fragestellung kommt es an',
      `<p>Wenn nur die Existenz eines passenden Auftrags interessiert, ist <b>EXISTS</b> oft klarer als ein JOIN mit nachträglichem <b>DISTINCT</b>. Die <b>Unterabfrage</b> darf mit der äußeren Kunden-ID korreliert sein; sie wird logisch für diesen Kunden beurteilt. <b>NOT IN</b> ist bei NULL in der <b>Unterabfrage</b> gefährlich: Der Vergleich kann UNKNOWN werden und unerwartet alle Kandidaten ausschließen. <b>NOT EXISTS</b> mit expliziter Beziehung vermeidet diesen konkreten Fallstrick.</p><p><b>Prüfungsantwort:</b> „Zuerst wird je Kunde <b>COUNT</b> berechnet; <b>AVG</b> arbeitet anschließend auf diesen Gruppenergebnissen. Die <b>Grundgesamtheit</b> bestimmt, ob Kunden ohne Bestellungen als null Bestellungen mitgerechnet werden.“</p>`,
      `<p>لا تختَر استعلامًا فرعيًا لمجرد أن السؤال يبدو صعبًا. إن كنت تحتاج قيمة واحدة فليعد <b>الاستعلام الداخلي</b> قيمة واحدة، وإن كنت تسأل عن وجود علاقة فاستخدم <b>EXISTS</b> بربط صحيح مع الصف الخارجي. نسيان الربط قد يجعل وجود طلب لأي عميل كافيًا لقبول جميع العملاء. انتبه أيضًا إلى NULL مع <b>NOT IN</b>؛ النتيجة ليست دائمًا قائمة العملاء الآخرين كما تتخيل. في الجواب الامتحاني اشرح الحساب الوسيط وحدود المجتمع المحسوب، ثم اكتب الاستعلام؛ هذه النقاط تبين أنك فهمت معنى المتوسط لا شكله فقط.</p>`)
  ], Q('Kunde enthält IDs1,2,3. Bestellung enthält (10,1),(11,1),(12,2). Berechne den mittleren Bestellungsbestand über alle drei Kunden, einschließlich Kunde3.',
    'SELECT AVG(1.0*x.anzahl) AS mittel FROM (SELECT k.id,COUNT(b.id) AS anzahl FROM Kunde k LEFT JOIN Bestellung b ON b.kunde_id=k.id GROUP BY k.id) AS x; Innere Zahlen2,1,0; Ergebnis1.0. COUNT(*) würde für Kunde3 fälschlich1 liefern.',
    'العميل الثالث يدخل بعدد صفر، لذلك نقسم مجموع ثلاثة طلبات على ثلاثة عملاء. وجوده في الجدول الرئيسي هو ما يسمح بتمثيله في النتيجة.', 8));
  deepen('sql-schreiben', [
    S('Durchgearbeitet: Constraints als letzte Schutzlinie',
      `<p>Bestand(artikel_id,menge) enthält (1,5),(2,0). Für jede Artikelnummer existiert höchstens eine Bestandszeile; negative Bestände sind verboten. Die Anwendung soll zwei Stück von Artikel1 reservieren. Eine vorherige <b>SELECT</b>-Prüfung allein genügt bei mehreren gleichzeitigen Nutzern nicht: Zwischen Prüfung und Änderung kann sich der Bestand ändern.</p>` + C('CREATE TABLE Bestand (\n  artikel_id INTEGER PRIMARY KEY,\n  menge INTEGER NOT NULL CHECK (menge >= 0)\n);\n\nUPDATE Bestand\nSET menge = menge - 2\nWHERE artikel_id = 1 AND menge >= 2;') + `<table><thead><tr><th>artikel_id</th><th>menge danach</th></tr></thead><tbody><tr><td>1</td><td>3</td></tr><tr><td>2</td><td>0</td></tr></tbody></table><p>Die <b>WHERE</b>-Bedingung verbindet Identifikation und ausreichenden Bestand. Die Anwendung muss zusätzlich die Zahl betroffener Zeilen prüfen:0 bedeutet, dass keine passende, ausreichend bestückte Zeile aktualisiert wurde. <b>CHECK</b> schützt die Datenbank auch vor anderen fehlerhaften Schreibwegen. Es ersetzt nicht die verständliche Fehlermeldung an den Benutzer. Wird die Reservierung zusammen mit einer Auftragsanlage ausgeführt, gehören beide Schritte in eine geeignete <b>Transaktion</b>. Für INSERT verwende explizite Spaltennamen; ein fehlender Pflichtwert wird nicht durch zufällige Spaltenreihenfolge geheilt. <b>Fremdschlüssel</b> ergänzen die Prüfung, dass der Artikel überhaupt existiert.</p>`,
      `<p><b>نريد خصم قطعتين من مخزون خمسة</b>، فتكون النتيجة ثلاثة. لا تكتب «اقرأ الكمية ثم إذا كانت كافية غيّرها» وتفترض أن البيانات لن تتغير بين العمليتين. جعل شرط الكفاية داخل UPDATE يمنع كتابة قيمة سالبة بهذا المسار. ومع ذلك افحص عدد الصفوف التي تغيّرت؛ الصفر لا يعني نجاح الحجز، بل عدم العثور على حالة مطابقة.</p><p>القيد <b>CHECK</b> ليس زرًا في <b>الواجهة</b>. هو قاعدة داخل قاعدة البيانات تُطبّق أيضًا عندما يأتي التعديل من برنامج آخر. <b>NOT NULL</b> يمنع الكمية المجهولة، وCHECK يمنع السالبة؛ وجود أحدهما لا يغني عن الآخر. إذا كان الحجز جزءًا من إنشاء طلب، فيجب أن تنجح الخطوتان معًا أو تتراجعا معًا. أما عرض رسالة واضحة للمستخدم فيبقى مسؤولية التطبيق، فلا تكتفِ بإظهار رسالة SQL خام قد تكشف تفاصيل داخلية أو لا تشرح سبب الرفض.</p>`),
    S('Rechte vergeben, ohne das Datenmodell zu beschädigen',
      `<p>Ein Auswertungsbenutzer braucht <b>SELECT</b>, aber normalerweise kein DROP und keine Bestandsänderung. <b>GRANT</b> gibt ein Recht auf ein bestimmtes Objekt; <b>REVOKE</b> entzieht dieses Recht. Weitere Rechte können je DBMS durch Rollen oder andere Grants fortbestehen. Bei DELETE prüfe Abhängigkeiten: <b>CASCADE</b> kann fachlich nützlich sein, aber etwa historische Rechnungsdaten ungewollt entfernen. „Benutzer deaktivieren“ ist häufig etwas anderes als „alle zugehörigen Vorgänge löschen“.</p><p><b>Prüfungsantwort:</b> „<b>PRIMARY KEY</b> sichert eindeutige Identifikation, <b>FOREIGN KEY</b> <b>referenzielle Integrität</b>, <b>NOT NULL</b> einen Pflichtwert und CHECK eine Wertebedingung. Rechte werden nach <b>Least Privilege</b> vergeben.“</p>`,
      `<p><b>ميّز حماية الشكل عن حماية الصلاحية:</b> FK يمنع الإشارة إلى منتج غير موجود، لكنه لا يقرر إن كان الموظف مخولًا ببيع المنتج. الصلاحيات والقواعد يكمل بعضها بعضًا. لا تعطِ مستخدم التقارير حق تعديل الجداول لأن ذلك أسهل في الإعداد. قبل DELETE أو <b>CASCADE</b> حدّد البيانات التابعة التي ستختفي، وهل يسمح المجال التجاري بذلك أصلًا. في الامتحان اربط اسم القيد بالخطأ الذي يمنعه، وأكمل <b>WHERE</b> في أوامر التعديل؛ غيابها قد يحوّل تغيير صف واحد إلى تغيير الجدول كله.</p>`)
  ], Q('Artikel(id,name) enthält ID1. Schreibe eine Tabelle Bewertung(id,artikel_id,sterne), in der Sterne nur1..5 und alle drei Werte Pflicht sind. Was passiert bei artikel_id99 beziehungsweise sterne0?',
    'CREATE TABLE Bewertung (id INTEGER PRIMARY KEY, artikel_id INTEGER NOT NULL REFERENCES Artikel(id), sterne INTEGER NOT NULL CHECK (sterne BETWEEN 1 AND 5)); ID99 scheitert am FK, da der Artikel fehlt. Sterne0 scheitert am CHECK. PRIMARY KEY schließt eine NULL-ID aus und verhindert doppelte IDs; mehrfache Bewertungen desselben Artikels bleiben erlaubt.',
    'كل خطأ له قيد مختلف: المنتج غير الموجود FK، والنجوم خارج المجال CHECK، والقيمة الناقصة NOT NULL. لا تضف UNIQUE على artikel_id دون أن يُطلب منع تعدد التقييمات.', 8));

  deepen('transaktion-nosql', [
    S('Durchgearbeitet: Eine Umbuchung ist eine fachliche Einheit',
      `<p><b>Konto(id</b>,guthaben) enthält (1,100.00),(2,20.00). Es sollen30 € von Konto1 nach Konto2 übertragen werden. Nach Erfolg müssen die Werte70 und50 betragen; die Gesamtsumme bleibt120. Zwei unabhängig bestätigte UPDATEs sind gefährlich: Ein Absturz nach der Abbuchung könnte Geld aus der sichtbaren Bilanz verschwinden lassen.</p>` + C('BEGIN;\nUPDATE Konto SET guthaben = guthaben - 30.00\nWHERE id = 1 AND guthaben >= 30.00;\n-- Anwendung prüft: genau eine Zeile geändert. Sonst ROLLBACK.\nUPDATE Konto SET guthaben = guthaben + 30.00 WHERE id = 2;\n-- Auch Ziel vorhanden? Bei Fehler ROLLBACK, sonst:\nCOMMIT;') + `<p>Die Zeilenzahlprüfungen sind hier Kommentare zu nötiger Anwendungslogik, keine ausführbaren SQL-Bedingungen. <b>Atomicity</b> verhindert einen dauerhaft halben Vorgang; <b>Consistency</b> verlangt die fachlichen Regeln. <b>Isolation</b> schützt vor unzulässiger Überlagerung konkurrierender Buchungen; das konkrete Isolationsniveau und die Sperren entscheiden über die Garantien. <b>Durability</b> betrifft bestätigte Daten nach definierten Ausfällen. Ein System muss außerdem Wiederholungen beherrschen: Bei verloren gegangener Antwort kann die Überweisung schon bestätigt sein. Eine eindeutige Vorgangs-ID hilft, denselben Auftrag beim Retry nicht zweimal auszuführen. <b>ACID</b> allein erkennt nicht, dass zwei technisch verschiedene Requests fachlich dieselbe Zahlung meinen.</p>`,
      `<p><b>المعاملة</b> <b>Transaktion</b> تجمع الخصم والإضافة بوصفهما عملية واحدة. النجاح يعني70 في الحساب الأول و50 في الثاني، لا تثبيت الخصم ثم محاولة الإضافة لاحقًا. إذا لم يوجد الحساب المستقبِل أو لم تكفِ الأموال، يجب أن يختار البرنامج <b>التراجع</b> وفق العقد، لا تثبيت نصف النتيجة.</p><p>التعليقات في المثال تمثل منطقًا مطلوبًا من التطبيق؛ كتابة BEGIN وCOMMIT حول أوامر لا تتحقق من نتائجها ليست حلًا كاملًا. ميّز أيضًا مشكلة <b>التزامن</b> عن تكرار الطلب: قد يحميك القفل من تحديث متداخل، لكنه لا يمنع مستخدمًا أو شبكة من إعادة إرسال نفس التحويل مرتين. لذلك نحتاج معرف عملية فريدًا لفحص التكرار عند الحاجة. لو انقطع الرد بعد <b>COMMIT</b>، لا تفترض أن التحويل فشل. استعلم عن حالة العملية ثم أعد المحاولة بطريقة آمنة، حتى لا يتحول علاج عطل الاتصال إلى خصم مزدوج.</p>`),
    S('Datenbankmodell nach Zugriff wählen, nicht nach Schlagwort',
      `<p>Für die Kontobuchung sind Beziehungen, atomare Änderungen und nachprüfbare Konsistenz entscheidend. Für einen kurzlebigen Sitzungs-<b>Cache</b> kann ein Key-Value-Speicher passen; flexible Produktdokumente können eine Dokumentdatenbank rechtfertigen. Die Wahl ersetzt keine Analyse von Aktualität, Ausfallverhalten, Transaktionen und Zugriffsmustern. „<b>NoSQL</b> hat keine Struktur“ oder „SQL ist immer langsamer“ sind unbrauchbare Pauschalaussagen.</p><p><b>Prüfungsantwort:</b> „Die Buchung braucht eine gemeinsame <b>Transaktion</b>, damit Abbuchung und Gutschrift nur zusammen wirksam werden. Zusätzlich sind Konkurrenzkontrolle, Ergebnisprüfung und sichere Wiederholung nötig.“ Begründe konkrete Schutzwirkungen statt nur die vier <b>ACID</b>-Buchstaben aufzuzählen.</p>`,
      `<p>إذا كان السؤال عن تحويل مالي فالأولوية لصحة القيود و<b>المعاملة</b>، لا لمرونة <b>JSON</b>. وإذا كان عن <b>Cache</b> فاسأل متى تنتهي صلاحيته وما أثر فقده. <b>NoSQL</b> اسم لمجموعة نماذج مختلفة، لا ضمان سرعة أو غياب معاملات. في الجواب الامتحاني اذكر نوع الوصول والضمان المطلوب، مثل منع نصف تحويل، ثم اربطه بالاختيار. <b>النسخة الاحتياطية</b> لا تصلح بديلًا عن معاملة صحيحة؛ هي تساعد <b>الاسترجاع</b> بعد فشل، بينما <b>المعاملة</b> تمنع حالات غير متسقة أثناء التشغيل المعتاد.</p>`)
  ], Q('Zwei Mitarbeiter lesen denselben Artikelbestand10, ziehen jeweils2 ab und speichern jeweils8. Beschreibe Soll-Ergebnis, Fehlerart und eine sichere Alternative.',
    'Sollbestand 6; Lost Update: Beide lesen den alten Wert 10 und überschreiben einander mit 8. Geeignete Alternative: UPDATE Bestand SET menge=menge-2 WHERE artikel_id=7 AND menge>=2; Zeilenzahl prüfen. Für mehrschrittige Vorgänge Transaktion mit passender Konkurrenzkontrolle, z.B. Sperre oder Versionsprüfung. Nur BEGIN/COMMIT um unkontrollierte Read-modify-write-Schritte garantiert nicht unabhängig vom Isolationsniveau die gewünschte Wirkung.',
    'التحديث الحسابي المباشر يستخدم الحالة الحالية بدل إعادة قيمة محسوبة من قراءة قديمة. إذا تعددت الخطوات فاذكر القفل أو الإصدار ومستوى العزل المناسب، لا كلمة Transaktion وحدها.', 8));

  deepen('sql-migration', [
    S('Durchgearbeitet: Ein Pflichtfeld ohne Datenverlust einführen',
      `<p>Kunde(id,name,email) enthält (1,Ada,ada@example.org),(2,Bilal,NULL),(3,Clara,NULL). Ab morgen soll email für jeden Kunden vorhanden sein. Ein sofortiges <b>NOT NULL</b> scheitert an den zwei fehlenden Werten. Die technische Änderung braucht deshalb eine fachliche Regel: Hier wurde freigegeben, die Kunden2 und3 mit nachrecherchierten, geprüften Adressen zu ergänzen. Erfundenen Sammeladressen würden wir echte Erreichbarkeit nur vortäuschen.</p>` + C("-- Beispiel ausdrücklich für PostgreSQL\nBEGIN;\nUPDATE Kunde SET email = 'bilal@example.org' WHERE id = 2;\nUPDATE Kunde SET email = 'clara@example.org' WHERE id = 3;\nSELECT id FROM Kunde WHERE email IS NULL;\n-- Erwartung: keine Zeilen. Prüfung im Migrationsablauf auswerten.\nALTER TABLE Kunde ALTER COLUMN email SET NOT NULL;\nCOMMIT;") + `<table><thead><tr><th>Prüfung danach</th><th>Erwartung</th></tr></thead><tbody><tr><td>COUNT(*) insgesamt</td><td>3 Kunden</td></tr><tr><td>COUNT(*) WHERE email IS NULL</td><td>0</td></tr><tr><td>Neuer Datensatz ohne email</td><td>Wird abgewiesen</td></tr></tbody></table><p><b>NOT NULL</b> prüft nur <b>Anwesenheit</b>, nicht E-Mail-Format oder Zustellbarkeit; auch ein leerer Text ist nicht NULL. Sichere vorher einen geeigneten Wiederherstellungsstand und teste die <b>Migration</b> mit realistischen Datenmengen. Während der Umstellung müssen neue Schreibvorgänge berücksichtigt werden. DBMS unterscheiden sich bei <b>DDL</b>-Transaktionen und Syntax; ein PostgreSQL-Ablauf lässt sich nicht blind auf jedes System übertragen.</p>`,
      `<p>المشكلة ليست فقط إضافة <b>NOT NULL</b>. توجد بيانات قديمة تخالف القيد الجديد، لذلك يجب تحديد معالجة مقبولة قبل تغيير البنية. اخترنا عناوين حقيقية تم التحقق منها، ثم فحصنا أن الاستعلام لا يعيد أي قيمة ناقصة، وبعدها فرضنا القيد. لا تستبدل كل NULL بعنوان وهمي وتقول إن جودة البيانات أصبحت صحيحة؛ أنت عالجت شرطًا شكليًا وأخفيت نقصًا تجاريًا.</p><p>قارن عدد العملاء قبل الترحيل وبعده، وافحص القيم المعدلة ثم اختبر محاولة كتابة سجل جديد مخالف. تذكّر أن النص الفارغ ليس NULL، وأن عدم الفراغ لا يثبت قابلية وصول البريد. المثال موسوم PostgreSQL لأن صياغة ALTER ودعم <b>التراجع</b> عن <b>DDL</b> يختلفان بين الأنظمة. في بيئة يعمل فيها المستخدمون أثناء التغيير، خطّط أيضًا لمنع إدخال قيم ناقصة جديدة بين خطوة الفحص وفرض القيد، مثل نافذة صيانة أو استراتيجية انتقال متوافقة.</p>`),
    S('Expand–Migrate–Contract und Rückfallstrategie',
      `<p><b>Bei größeren Änderungen</b> ist ein dreistufiger Übergang sinnvoll: neue Struktur ergänzen, Daten kontrolliert migrieren, Anwendung umstellen und erst danach alte Struktur entfernen. Ein sofortiges DROP der alten Namensspalte verhindert Vergleiche und kann Informationen verlieren; Personennamen lassen sich nicht zuverlässig am ersten Leerzeichen zerlegen. Dokumentiere Ausnahmen und prüfe Stichproben sowie Summen/Anzahlen.</p><p><b>Prüfungsantwort:</b> „Zuerst fehlende Werte nach fachlicher Regel bereinigen, Vollständigkeit prüfen, dann <b>NOT NULL</b> setzen und das Anwendungsschreiben anpassen.“ Ein <b>Rollbackplan</b> sagt konkret, welche Daten und Versionen wiederhergestellt werden; ein ungeprüftes Backupversprechen reicht nicht.</p>`,
      `<p>احفظ البنية القديمة حتى تتأكد أن التطبيق والبيانات يعملان مع الجديدة. فصل الاسم إلى كلمتين تلقائيًا قد يفسد أسماء مركبة، لذلك اذكر الحدود والاستثناءات بدل الادعاء أن كل فراغ يفصل الاسم الأول عن العائلة. في الامتحان يكفي تسلسل واضح مع فحص قبل القيد وفحص بعده، ولهجة SQL محددة. أما في التشغيل الفعلي فاضف ترتيب نسخ التطبيق وإجراءات الرجوع ومراقبة الأخطاء. <b>التراجع</b> لا يعني حذف الأعمدة الجديدة عشوائيًا إذا كانت قد استقبلت معلومات لا توجد في النسخة القديمة.</p>`)
  ], Q('Produkt(id,preis) enthält (1,10),(2,-5),(3,NULL). Künftig soll preis NOT NULL und >=0 sein. Beschreibe Migration, ohne unbekannte Preise zu erfinden.',
    'Fehlerhafte/fehlende Preise mit SELECT id,preis FROM Produkt WHERE preis IS NULL OR preis<0 identifizieren. Mit Fachverantwortlichen korrekte Werte klären oder Datensätze ausdrücklich nach Regel sperren/aussondern; nicht still0 erfinden. Nach Bereinigung Prüfmenge erneut kontrollieren. PostgreSQL z.B. ALTER TABLE Produkt ALTER COLUMN preis SET NOT NULL; ALTER TABLE Produkt ADD CONSTRAINT preis_nichtnegativ CHECK(preis>=0); Schreibpfade anpassen und Testfälle für NULL/-1/0 ergänzen.',
    'السعر المفقود ليس مجانيًا. اجمع معالجة البيانات القديمة مع منع الخطأ مستقبلًا، وافحص الصفر لأنه حد صحيح هنا وليس قيمة سالبة.', 9));
  deepen('testarten', [
    S('Durchgearbeitet: Dieselbe Bestellung auf vier Teststufen',
      `<p><b>Ein Shop berechnet Versandkosten:</b> Bei einem gültigen Warenwert ab50 € ist der Versand kostenlos, darunter kostet er4,90 €. Negative Warenwerte werden abgewiesen. Die Anwendung speichert eine Bestellung und zeigt anschließend eine Bestätigung. Ein einziges „Bestellung klappt“-Testergebnis kann nicht alle beteiligten Risiken abdecken.</p><table><thead><tr><th>Stufe / Eingabe</th><th>Erwartung</th><th>Warum hier?</th></tr></thead><tbody><tr><td>Unit: versand(49.99)</td><td>4.90</td><td>Isolierte Berechnungsregel</td></tr><tr><td>Unit: versand(50.00)</td><td>0.00</td><td>Inklusive Freigrenze</td></tr><tr><td>Integration: Bestellung mit2 Positionen speichern/laden</td><td>Beide Positionen und Summe unverändert</td><td>Zusammenarbeit Service/DB</td></tr><tr><td>System: erlaubter Benutzer bestellt im Browser</td><td>Bestätigung, gespeicherter Auftrag, korrekte Gesamtsumme</td><td>Gesamter Arbeitsablauf</td></tr><tr><td>Abnahme: vereinbarter Kundenfall mit50 € Warenwert</td><td>Kunde bestätigt erfülltes Akzeptanzkriterium</td><td>Fachliche Eignung aus Auftraggebersicht</td></tr></tbody></table><p>Eine Fake-Datenbank im <b>Unit-Test</b> ermöglicht schnelle, kontrollierte Fehlerfälle; sie beweist nicht, dass echtes SQL und Transaktionen funktionieren. Ein <b>Integrationstest</b> mit echter Testdatenbank ergänzt diese Lücke. Der <b>Systemtest</b> kann zusätzlich Browserkonfiguration und Berechtigungen entdecken. Abnahme entscheidet über die vereinbarten Anforderungen, nicht bloß über die technische Durchführbarkeit. Teststufe und Auswahlverfahren sind getrennte Dimensionen: Die Versandgrenze lässt sich als <b>Black-Box</b>-Anforderung testen; eine Codeverzweigung lässt sich zusätzlich mit <b>White-Box</b>-Kriterien prüfen.</p>`,
      `<p>نفس العملية تحتاج اختبارات بأهداف مختلفة. <b>Unit-Test</b> يفحص دالة تكلفة الشحن دون الاعتماد على المتصفح أو قاعدة البيانات. <b>Integrationstest</b> يثبت أن المكونات تتبادل البيانات فعلًا، مثل حفظ أسطر الطلب واسترجاعها. <b>Systemtest</b> يجرب التدفق الكامل، بينما <b>Abnahmetest</b> يرتبط بما اتفق عليه العميل ويقرر قبول الوظيفة.</p><p>لا تنتظر <b>اختبار النظام</b> حتى تعرف أن50 يورو يجب أن تعني شحنًا مجانيًا؛ هذه قاعدة صغيرة يمكن اختبارها بسرعة وبحالات كثيرة. وفي المقابل نجاح الدالة لا يثبت أن التطبيق سيعرض قيمتها أو يخزنها بشكل صحيح. استخدام Fake داخل الاختبار مفيد للعزل، لكنه لا يختبر SQL الحقيقي. الجدول ليس تكرارًا لنفس الفحص أربع مرات، بل توزيع للمخاطر على مستويات مناسبة. عند السؤال عن نوع الاختبار اذكر ما هو معزول وما هي المكونات الحقيقية المشاركة، ثم علّل التصنيف بهذه القرينة.</p>`),
    S('Testfälle aus dem Risiko ableiten und eindeutig protokollieren',
      `<p>Ein Testfall braucht Ausgangszustand, Eingabe/Schritte und eine prüfbare Erwartung. „Kein Absturz“ reicht nicht, wenn eine genaue Versandgebühr gefordert ist. Für eine negative Eingabe muss der Vertrag festlegen, ob eine <b>Exception</b>, ein Fehlerobjekt oder eine Meldung entsteht. „Fehler“ ohne beobachtbares Kriterium ist keine präzise Soll-Angabe.</p><p><b>Prüfungsantwort:</b> „Der <b>Komponententest</b> prüft die Berechnungslogik isoliert. Der <b>Integrationstest</b> prüft die echte Speicherung und das Zusammenspiel der Komponenten.“ Für einen gefundenen Defekt Version, Daten, Schritte, Soll/Ist und Reproduzierbarkeit dokumentieren. Wiederholung nach einer Korrektur ist zusätzlich ein <b>Regressionstest</b>; das ist keine alternative Teststufe.</p>`,
      `<p>لا تكتب نتيجة متوقعة مثل «يعمل جيدًا». حدّد الرسوم أو رمز الخطأ أو عدم إنشاء السجل حسب المواصفة. إذا لم تحدد المواصفة سلوك الإدخال السالب فاذكر هذا النقص قبل اختراع توقع. في تقرير العطل اكتب الإصدار والخطوات والبيانات والفرق بين المتوقع والحاصل، كي يعيد شخص آخر الحالة. <b>Regression</b> يصف غرض الفحص بعد التغيير، ويمكن أن يوجد في اختبار وحدة أو تكامل أو نظام. بهذه الطريقة تتجنب حفظ أسماء الاختبارات كأنها أصناف متعارضة على مستوى واحد.</p>`)
  ], Q('Eine Rabattfunktion wird mit Fake-Kundendaten geprüft. Danach testest du dieselbe Funktion zusammen mit echtem Kundendienst und Testdatenbank. Ordne beide Stufen zu und formuliere einen vollständigen Grenztest: Rabatt gilt ab100 €.',
    'Erster Test: Komponententest, sofern Abhängigkeiten kontrolliert ersetzt sind. Zweiter: Integrationstest der beteiligten Komponenten. Grenztest z.B. Vorbedingung berechtigter Kunde und definierter Rabatt10%; Eingabe Warenwert100.00; Erwartung Rabatt10.00, zu zahlender Warenwert90.00, ohne Rundungs-/Steuerannahmen zu erfinden. Ergänze99.99 ohne Rabatt und100.01 mit Rabatt nach festgelegter Rundungsregel.',
    'التصنيف يتعلق بنطاق الاختبار، أما حالة الحد فتحتاج مدخلًا ومخرجات قابلة للتحقق. عرّف نسبة الخصم إذا لم يعطها السؤال قبل استخدام أرقام ناتجة عنها.', 8));

  deepen('testfaelle', [
    S('Durchgearbeitet: Eine kleine Tabelle deckt die Regelgrenzen auf',
      `<p><b>Die Funktion lieferbar(menge</b>,bestand) akzeptiert nur ganze Bestellmengen von1 bis10 und liefert TRUE, wenn zusätzlich genügend Bestand vorhanden ist. Ungültige Mengen erzeugen den definierten Fehler „Menge ungültig“; Bestand ist laut Funktionsvertrag eine nichtnegative ganze Zahl. Die beiden fachlichen Prüfungen dürfen nicht verwechselt werden: Menge11 ist ungültig, selbst wenn100 Stück vorhanden sind.</p><table><thead><tr><th>Menge / Bestand</th><th>Erwartung</th><th>Grund</th></tr></thead><tbody><tr><td>0 /10</td><td>Fehler</td><td>Unterhalb gültiger Menge</td></tr><tr><td>1 /1</td><td>TRUE</td><td>Untere gültige Grenze, Bestand genau ausreichend</td></tr><tr><td>10 /10</td><td>TRUE</td><td>Obere Grenze eingeschlossen</td></tr><tr><td>11 /100</td><td>Fehler</td><td>Oberhalb gültiger Menge</td></tr><tr><td>5 /4</td><td>FALSE</td><td>Gültige Menge, zu wenig Bestand</td></tr><tr><td>5 /5</td><td>TRUE</td><td>Vergleich muss Gleichheit zulassen</td></tr><tr><td>2.5 /10</td><td>Fehler</td><td>Keine ganze Bestellmenge</td></tr></tbody></table><p>Die Tabelle kombiniert <b>Äquivalenzklassen</b> mit Grenzen und zwei zusammengesetzten Bedingungen. Ein Test mit Menge5/Bestand100 allein beweist kaum etwas über die Grenzen. Erwartete Ergebnisse werden vor dem Programmlauf aus der Spezifikation abgeleitet. Sind Typen bereits statisch auf Integer festgelegt, wird2.5 gegebenenfalls an einer vorgeschalteten Eingabegrenze geprüft; der Testumfang muss die tatsächlich betrachtete Schnittstelle nennen.</p>`,
      `<p><b>قسّم المشكلة إلى صلاحية الكمية وكفاية المخزون</b>. قد تكون الكمية صحيحة لكن غير متوفرة، فتكون النتيجة FALSE؛ وقد تكون خارج المدى أصلًا، فتنتج رسالة خطأ مختلفة. هذا الفرق يحدد حالات اختبار منفصلة ولا يجوز دمجه بكلمة «فشل» عامة.</p><p>اختبار1 مع مخزون1 يكشف الحد الأدنى والمساواة، واختبار10 يكشف الحد الأعلى، و11 يمنع استخدام ≤11 بالخطأ. الزوج5/4 يقيس نقص المخزون، و5/5 يكشف كتابة مقارنة صارمة > بدل ≥. لا تحتاج كل الأعداد بين1 و10 إذا كانت تشكل فئة متكافئة، لكن <b>الحالات الحدودية</b> لها قيمة إضافية. القيم غير الصحيحة مثل2.5 تُختبر عند <b>الواجهة</b> التي تستطيع استقبالها؛ إن كانت الدالة داخلية بنوع Integer فلا تتظاهر أن إدخال نص إليها ممكن في المستوى نفسه. اربط كل حالة بسببها حتى تعرف أي خطأ محتمل تكشفه.</p>`),
    S('Coverage verstehen statt die Prozentzahl überschätzen',
      `<p>Bei <code>A UND B</code> können zwei Tests beide Entscheidungszweige durchlaufen, ohne jeden Teil der Logik sinnvoll zu prüfen: TRUE/TRUE und FALSE/FALSE reichen für <b>Entscheidungsüberdeckung</b>, prüfen aber nicht TRUE/FALSE. <b>Kurzschlussauswertung</b> kann B im zweiten Fall sogar überspringen. <b>Bedingungsüberdeckung</b> betrachtet Teilbedingungen; <b>Pfadüberdeckung</b> betrachtet Ablauffolgen und ist mit unbeschränkten Schleifen oft nicht vollständig erreichbar.</p><p><b>Prüfungsantwort:</b> „Ich wähle je einen Repräsentanten gültiger und ungültiger Klassen sowie Werte direkt an den Grenzen. Zusätzlich prüfe ich fachlich verschiedene Kombinationen.“ Nenne für <b>Coverage</b> immer Zähler und Nenner;100% ist keine Aussage über fehlende Anforderungen oder die Richtigkeit der erwarteten Ergebnisse.</p>`,
      `<p>وصول الاختبار إلى كل سطر لا يعني أنه كشف كل خطأ. قد يُنفذ السطر ببيانات واحدة فقط، أو تكون النتيجة المتوقعة نفسها خاطئة. مع شرط AND يمكن لفشل الشرط الأول أن يمنع تقييم الثاني، لذلك راقب ما تم تنفيذه فعلًا. ميّز عدد الفروع المغطاة عن عدد الاختبارات الناجحة؛ نسبتان مختلفتان. جوابك الامتحاني الأفضل يذكر معيار الاختيار وحالاته وحدود الضمان، ولا يكتفي بأن «نكتب اختبارات كثيرة». كثرة بيانات متشابهة لا تعوض غياب <b>حالة الحد</b> الحاسمة.</p>`)
  ], Q('Einlass gilt für alter>=18 UND hatTicket. Gib eine Entscheidungstabelle mit vier Kombinationen an. Reichen zwei Tests für Zweigüberdeckung und warum beweist das keine vollständige Bedingungsprüfung?',
    '18/TRUE→Einlass;18/FALSE→Ablehnung;17/TRUE→Ablehnung;17/FALSE→Ablehnung. TRUE/TRUE und FALSE/FALSE erreichen Ja- und Nein-Zweig. Bei Kurzschluss wird im zweiten Test hatTicket eventuell nicht ausgewertet; TRUE/FALSE fehlt. Deshalb ist Zweigüberdeckung nicht automatisch gleich Bedingungsüberdeckung oder vollständiger Fehlererkennung.',
    'اكتب التركيبات الأربع ونتيجة كل منها. فرع الرفض واحد لكنه قد ينتج من أسباب مختلفة؛ تغطيته مرة لا تثبت اختبار كل سبب منطقي.', 8));

  deepen('unit-debug', [
    S('Durchgearbeitet: Zwei kleine Fehler, mehrere verräterische Testfälle',
      `<p>Die Funktion <b>minimum</b> akzeptiert eine nichtleere Liste ganzer Zahlen; NULL und leere Liste sollen einen definierten Fehler auslösen. Im folgenden Entwurf verbergen sich zwei unabhängige Fehler. Verfolge die Werte mit der Tabelle, bevor du Änderungen vorschlägst.</p>` + C('funktion minimum(werte):\n  wenn werte == null ODER länge(werte) == 0: Fehler\n  kleinster = 0\n  für i = 0; i < länge(werte)-1; i++:\n    wenn werte[i] < kleinster: kleinster = werte[i]\n  rückgabe kleinster') + `<table><thead><tr><th>Eingabe</th><th>Soll</th><th>Ist im Entwurf</th><th>Hinweis</th></tr></thead><tbody><tr><td>[4,7,2]</td><td>2</td><td>0</td><td>Falsche Initialisierung</td></tr><tr><td>[-4,-7,-2]</td><td>-7</td><td>-7</td><td>Ein grüner Test verdeckt Fehler</td></tr><tr><td>[-4,2,-9]</td><td>-9</td><td>-4</td><td>Letztes Element übersprungen</td></tr><tr><td>[5]</td><td>5</td><td>0</td><td>Schleife läuft nie</td></tr><tr><td>[] / NULL</td><td>Definierter Fehler</td><td>Fehler</td><td>Vertrag für Sonderfälle</td></tr></tbody></table><p><b>Die Initialisierung0</b> ist kein tatsächlicher Listenkandidat und scheitert bei positiven Werten. Der Schleifenvergleich überspringt den letzten Index. Korrektur: Initialisiere mit werte[0] und beginne die Schleife bei1; gehe bis zur exklusiven Grenze länge(werte). Jetzt funktionieren auch Singleton und negative Listen. Behebe nicht nur das erste sichtbare Symptom: Nach jeder Änderung alle relevanten Fälle erneut ausführen.</p>` + C('kleinster = werte[0]\nfür i = 1; i < länge(werte); i++:\n  wenn werte[i] < kleinster: kleinster = werte[i]\nrückgabe kleinster'),
      `<p><b>تتبّع الخطأ على الورق بدل تغيير الكود عشوائيًا</b>. في القائمة الموجبة لا يوجد عنصر أصغر من الصفر، فيبقى الجواب صفرًا رغم أنه ليس عنصرًا أصلًا. وفي القائمة التي أصغر عناصرها آخر عنصر، تمنع حدود الحلقة فحصه. هذان سببان مستقلان، لذلك إصلاح التهيئة وحده لا يكفي.</p><p>ابدأ بأول عنصر حقيقي بعد <b>فحص NULL</b> و<b>القائمة الفارغة</b>، ثم افحص العناصر المتبقية حتى آخر فهرس. القائمة ذات العنصر الواحد مهمة لأنها تختبر الحالة التي لا تدخل الحلقة؛ يجب أن تعيد قيمة ذلك العنصر. نجاح القائمة السالبة الثانية لا يثبت سلامة الدالة، بل يبيّن لماذا نحتاج حالات متنوعة. في جواب الامتحان اذكر السبب والموقع والتصحيح ونتيجة الاختبارات، وليس «هناك خطأ في for» فقط. أضف كل حالة كشفت خطأ إلى <b>اختبارات <b>Regression</b></b> كي لا يعود عند تعديل لاحق.</p>`),
    S('Aus einem Defekt einen dauerhaften Test machen',
      `<p>Ein <b>Unit-Test</b> richtet eine feste Liste ein (<b>Arrange</b>), ruft minimum auf (<b>Act</b>) und vergleicht exakt mit dem Sollwert (<b>Assert</b>). Ein Test ohne Assertion kann erfolgreich enden, obwohl ein falscher Rückgabewert entsteht. Bei erwarteten Fehlern muss der Test die vereinbarte Fehlerart prüfen, nicht jede beliebige <b>Exception</b> akzeptieren. Für zustandsabhängigen Code setze Uhr, Zufall und Abhängigkeiten kontrolliert.</p><p><b>Prüfungsantwort:</b> „Die Initialisierung muss ein vorhandener Kandidat sein; die exklusive Schleifengrenze muss auch den letzten Index erfassen. Grenztests sind Singleton, leere Liste und Minimum am Ende.“ <b>Debugger</b> helfen den Ablauf zu sehen; der <b>Regressionstest</b> hält die Fehlererkenntnis anschließend automatisiert fest.</p>`,
      `<p><b>اختبار الوحدة</b> يحتاج مقارنة صريحة؛ استدعاء الدالة دون فحص الناتج لا يثبت صحتها. إذا توقعنا خطأ بسبب قائمة فارغة، فتأكد من نوع الخطأ المقصود، لا أي انهيار عرضي. اجعل البيانات ثابتة والاختبارات مستقلة حتى لا يتغير الفشل مع ترتيب التشغيل. اكتب في الشرح لماذا يصلح التعديل لكل الحالات المطلوبة، ثم أعد فحص الحالات السابقة، بما فيها التي كانت ناجحة. Test Regression يحفظ الحالة التي كشفت العيب، أما <b>Debugger</b> فهو أداة للوصول إلى السبب أثناء التحليل.</p>`)
  ], Q('Eine Funktion maximum startet mit0 und durchläuft alle Elemente korrekt. Für welche Eingaben fällt sie auf, was ist die Reparatur, und wie sieht Arrange–Act–Assert aus?',
    'Bei ausschließlich negativen Werten z.B.[-8,-3,-5] liefert sie fälschlich0 statt-3. Nach Vertragsprüfung auf null/leer maximum=werte[0] setzen und ab Index1 iterieren. Arrange: feste Liste[-8,-3,-5]; Act: maximum aufrufen; Assert: Ergebnis==-3. Ergänze Singleton[-4], Maximum am Ende, gleiche Werte und definierte Fehlerfälle.',
    'الصفر ليس مرشحًا صالحًا تلقائيًا. تعكس المسألة مشكلة minimum: هذه المرة تكشفها القيم السالبة لا الموجبة. اكتب التوقع الدقيق حتى يلتقط الاختبار الخطأ.', 8));

  deepen('git-tools', [
    S('Durchgearbeitet: Eine Korrektur nachvollziehbar ins Team bringen',
      `<p><b>Ausgangslage:</b> Der lokale main-Zweig ist sauber und mit origin/main synchron. Du korrigierst die Versandgrenze von größer50 auf mindestens50. Das Team integriert Änderungen per <b>Review</b>. Ein Branch hält diese Korrektur getrennt; ein <b>Regressionstest</b> für genau50 dokumentiert die fachliche Absicht.</p>` + C('git switch -c fix-versandgrenze\n# Code ändern und Testfall für genau 50.00 ergänzen\ngit diff\ngit add versand.js versand.test.js\ngit diff --staged\ngit commit -m "Versand ab 50 Euro kostenlos berechnen"\ngit push -u origin fix-versandgrenze') + `<p>Nach git diff erwartest du nur die beabsichtigte Bedingung und den neuen Test. add übernimmt diese Dateien in den Index; diff --staged zeigt genau den Inhalt des nächsten Commits. <b>commit</b> erzeugt die lokale Historie, push teilt sie mit dem Remote. Anschließend wird ein <b>Review</b> angelegt und die CI prüft die Änderung. fetch lädt fremde Historie, ändert aber nicht automatisch deinen Arbeitsstand. Wenn main inzwischen weiterlief, integrierst du die Änderungen nach Teamregel und löst Konflikte fachlich. Nach einer Konfliktauflösung sind Tests erneut nötig: Das bloße Entfernen der Konfliktmarkierungen beweist nicht, dass die richtige Grenze erhalten blieb. Der <b>Pull Request</b> selbst ist kein Git-<b>Commit</b> und kein Nachweis bestandener Tests.</p>`,
      `<p><b>افترضنا بداية نظيفة حتى يكون تسلسل الخطوات واضحًا</b>. الفرع يخص إصلاحًا واحدًا، والاختبار عند50 يشرح لماذا تغيّرت المقارنة. git diff يعرض ما عدّلته قبل إضافته، وgit diff --staged يعرض ما سيدخل الالتزام فعلًا. قد تختلف المجموعتان إذا أضفت بعض التغييرات فقط، لذلك لا تخلط الملف المحفوظ مع النسخة الموجودة في Index.</p><p><b>commit</b> محلي، وpush ينقل الالتزامات إلى <b>المستودع البعيد</b>، وبعدها يمكن للفريق مراجعتها. إذا حدث تعارض فافهم النتيجة التجارية المطلوبة ولا تختَر نسختك آليًا. قد يزيل اختيار عشوائي إصلاح زميل أو يعيد الخطأ. بعد الدمج أعد الاختبارات المناسبة. اجعل رسالة الالتزام تشرح التغيير، ولا تجمع إعادة تنسيق ملفات كثيرة مع إصلاح حد واحد لأن ذلك يصعّب المراجعة. استثناء secrets في <b>gitignore</b> لا يزيل ما سبق نشره في التاريخ؛ إذا تسرّب مفتاح فتعامل معه كمفتاح مكشوف يحتاج إبطالًا.</p>`),
    S('Eine Pipeline sinnvoll prüfen und einen Rückweg vorbereiten',
      `<table><thead><tr><th>Prüfeingabe</th><th>Erwartung</th><th>Grund</th></tr></thead><tbody><tr><td>Warenwert49.99</td><td>Versand4.90</td><td>Altes gültiges Verhalten erhalten</td></tr><tr><td>Warenwert50.00</td><td>Versand0.00</td><td>Korrigierte Grenze</td></tr><tr><td>Warenwert50.01</td><td>Versand0.00</td><td>Bereich oberhalb bleibt korrekt</td></tr></tbody></table><p>CI baut und testet regelmäßig integrierte Änderungen. Eine grüne Pipeline bedeutet nur, dass ihre konkreten Prüfungen bestanden sind. <b>Continuous Delivery</b> hält eine auslieferbare Version bereit; <b>Continuous Deployment</b> kann sie automatisch ausrollen. Bei einem bereits geteilten fehlerhaften <b>Commit</b> erzeugt <b>revert</b> typischerweise einen nachvollziehbaren Gegencommit; ein pauschales <b>reset --hard</b> kann lokale Arbeit verwerfen und ersetzt keinen abgestimmten Teamablauf.</p><p><b>Prüfungsantwort:</b> „Ich prüfe den Diff, stage gezielt, committe lokal, pushe und lasse <b>Review</b>/CI laufen. Der <b>Grenztest</b> sichert die Korrektur als <b>Regressionstest</b>.“</p>`,
      `<p>نجاح Pipeline لا يعني وجود فحص لكل المتطلبات؛ يعني أن الفحوص الموجودة نجحت. الجدول يعرض المدخلات والمتوقع وسبب كل حالة، حتى لا نفحص الحد الجديد ونكسر الجانب القديم دون ملاحظة. <b>revert</b> يحافظ على أثر <b>التراجع</b> في التاريخ بعملية جديدة، بينما reset يغيّر موضع المرجع وقد يمحو عملًا حسب الخيار. في الامتحان ميّز النقل إلى Remote عن إنشاء نسخة محلية، وميّز <b>التراجع</b> التقني عن قرار نشره في نظام مستخدمين. المطلوب تسلسل يمكن تتبعه وفحصه، لا أكبر عدد من أوامر Git.</p>`)
  ], Q('Nach git add änderst du dieselbe Datei erneut. Was enthält ein sofortiger git commit, wie prüfst du das, und warum löst gitignore ein eingechecktes Passwort nicht?',
    'Commit übernimmt den Indexstand zum Zeitpunkt des letzten add, nicht automatisch die spätere Arbeitskopie. git diff zeigt unstaged Änderungen; git diff --staged den vorgesehenen Commit. Gewünschte weitere Änderungen gezielt erneut stagen. gitignore betrifft üblicherweise nicht bereits getrackte Historie; ein veröffentlichtes Passwort muss als kompromittiert betrachtet und widerrufen/geändert werden, zusätzlich bereinigt man Repository/Prozess nach Teamvorgaben.',
    'يوجد فرق بين الملف في مساحة العمل ونسخته داخل Index. ملف التجاهل لا يسحب سرًا من تاريخ شاهده الآخرون؛ تغيير السر نفسه ضروري.', 7));
})();

